// Запуск приложения и вход тестового аккаунта (по номеру и тестовому OTP из .qa/accounts.env — значения подставляются только при прогоне).
import { $, driver } from '@wdio/globals';
import { byText, byTextContains, tapText } from './ui.ts';

const ACCOUNT = (process.env.APP_ACCOUNT || 'USER1').toUpperCase();   // USER1 | USER2

export async function isLoggedIn() {
  return (await byText('בית')).isDisplayed().catch(() => false);
}

/** Вход: «בואו נתחיל» → «מספר נייד» → «שילחו קוד אימות» → код. Выполняется один раз (noReset сохраняет сессию).
 *  account: USER1 | USER2 | ADMIN (аккаунт клиента — в приложении у него есть админка). */
export async function login(account: string = ACCOUNT) {
  const phone = process.env[`QA_${account}_PHONE`];
  const otp = process.env[`QA_${account}_OTP`];
  if (!phone || !otp) {
    if (account === 'ADMIN') {
      // Код админа показывается на экране (тестовый режим) — вход делает человек; ждём главный экран до 5 минут.
      console.log('[app-e2e] Войдите вручную под аккаунтом клиента (админ) — тест ждёт главный экран…');
      await (await byText('בית')).waitForDisplayed({ timeout: 300000 });
      return;
    }
    throw new Error(`Нет QA_${account}_PHONE / QA_${account}_OTP в .qa/accounts.env`);
  }
  const start = await byText('בואו נתחיל');
  if (await start.isDisplayed().catch(() => false)) await start.click();
  const field = await (driver.isAndroid
    ? $('android=new UiSelector().className("android.widget.EditText")')
    : $('-ios class chain:**/XCUIElementTypeTextField'));
  await field.waitForDisplayed();
  await field.clearValue();                        // поле заранее заполнено мокап-номером — это норма
  await field.setValue(phone);
  await tapText('שילחו קוד אימות');
  const codeField = await (driver.isAndroid
    ? $('android=new UiSelector().className("android.widget.EditText")')
    : $('-ios class chain:**/XCUIElementTypeTextField'));
  await codeField.waitForDisplayed();
  // Код — отдельные клетки «ספרה N מתוך <число>»: одной строкой в первое поле теряется цифра (было «134» вместо «1234»).
  // С 26.10/03.11 код 6 цифр («ספרה N מתוך שש», SMS Pulseem); 4 клетки («ארבע») — старые сборки.
  const sizes: Array<[number, string]> = [[6, 'שש'], [4, 'ארבע']];
  let cells: number = 0; let word = '';
  for (const [n, w] of sizes) if (await $(`~ספרה 1 מתוך ${w}`).isExisting()) { cells = n; word = w; break; }
  if (cells && otp.length !== cells) {
    // Тестовый OTP не той длины (вход только реальным SMS с 28.10) — код вводит человек.
    console.log(`[app-e2e] OTP в accounts.env (${otp.length} цифр) ≠ ${cells} клеток — введите код из SMS вручную, тест ждёт главный экран…`);
    await (await byText('בית')).waitForDisplayed({ timeout: Number(process.env.QA_MANUAL_WAIT || 600000) });
  } else {
    if (cells) {
      for (let i = 0; i < cells; i++) {
        const cell = await $(`~ספרה ${i + 1} מתוך ${word}`);
        await cell.click();
        await cell.addValue(otp[i]);
        await driver.pause(200);
      }
    } else {
      await codeField.setValue(otp);
    }
    // Код подтверждается кнопкой «שלח» (iOS и Pixel 6: она под клавиатурой — клавиатуру прячем ДО нажатия).
    if (driver.isAndroid && (await driver.isKeyboardShown().catch(() => false))) await driver.hideKeyboard().catch(() => {});
    const send = await $('~שלח');
    if (await send.isExisting()) await send.click().catch(() => {});
    await (await byText('בית')).waitForDisplayed({ timeout: 30000 });
  }
  // Окно уровня «עלית דרגה» могло появиться — закрыть, если есть.
  const close = await byTextContains('סגירה');
  if (await close.isDisplayed().catch(() => false)) await close.click();
}

/** Закрыть окно, оставшееся от предыдущего теста (достижение, «עלית דרגה» и т.п.). */
export async function dismissModals() {
  for (let i = 0; i < 3; i++) {
    const close = await $('~סגירה');
    if (!(await close.isExisting())) return;
    await close.click().catch(() => {});
    await driver.pause(500);
  }
}

export async function ensureAppReady() {
  // Каждый файл тестов — с чистого запуска: главный экран, без окон и зависаний от предыдущего файла.
  const appId = driver.isIOS ? process.env.APP_IOS_BUNDLE : process.env.APP_ANDROID_PACKAGE;
  if (appId) {
    await driver.terminateApp(appId).catch(() => {});
    await driver.activateApp(appId);
    await driver.pause(4000);
  }
  await dismissModals();
  if (!(await isLoggedIn())) await login();
}

/** Вернуться на главный экран между тестами. */
export async function toHome() {
  for (let i = 0; i < 4 && !(await isLoggedIn()); i++) await driver.back();
  await tapText('בית');
}

/** Выйти из аккаунта: профиль («מעבר לפרטים שלי») → «התנתקות» (+ подтверждение, если есть) → экран входа. */
export async function logout() {
  await toHome();
  const { tapLabel, scrollToText } = await import('./ui.ts');
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToText('התנתקות')).click();
  await driver.waitUntil(async () => {
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) return true;
    const confirm = await byText('התנתקות');
    if (await confirm.isDisplayed().catch(() => false)) await confirm.click().catch(() => {});
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: 'после «התנתקות» не открылся экран входа' });
}

/** Сменить аккаунт на одном телефоне (например, админ утверждает → пользователь проверяет). */
export async function switchAccount(account: 'USER1' | 'USER2' | 'ADMIN') {
  await logout();
  await login(account);
}
